      transition: transform 0.2s;
    }

    .modal-overlay.active .modal {
      transform: scale(1);
    }

    .modal-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 1.25rem 1.5rem;
      border-bottom: 1px solid var(--color-border);
    }

    .modal-title {
      font-size: 1.125rem;
      font-weight: 600;
      color: var(--color-text);
    }

    .modal-close {
      background: none;
      border: none;
      cursor: pointer;
      padding: 0.5rem;
      color: var(--color-link);
      transition: color 0.2s;
    }

    .modal-close:hover {
      color: var(--color-text);
    }

    .modal-close svg {
      width: 20px;
      height: 20px;
      display: block;
    }

    .modal-body {
      padding: 1.5rem;
    }

    .preference-group {
      margin-bottom: 1.5rem;
    }

    .preference-group:last-child {
      margin-bottom: 0;
    }

    .preference-label {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      cursor: pointer;
    }

    .preference-checkbox {
      width: 18px;
      height: 18px;
      accent-color: var(--color-primary);
      cursor: pointer;
    }

    .preference-text {
      font-size: 0.9375rem;
      color: var(--color-text);
    }

    .preference-description {
      font-size: 0.8125rem;
      color: var(--color-muted);
      margin-top: 0.25rem;
      margin-left: 2.25rem;
    }

    .modal-footer {
      padding: 1.25rem 1.5rem;
      border-top: 1px solid var(--color-border);
      display: flex;
      justify-content: flex-end;
    }

    .modal-save-btn {
      font-size: 0.9375rem;
      font-weight: 500;
      font-family: inherit;
      padding: 0.625rem 1.25rem;
      background-color: var(--color-primary);
      color: var(--color-bg);
      border: none;
      border-radius: 6px;
      cursor: pointer;
      transition: background-color 0.2s;
    }

    .modal-save-btn:hover {
      background-color: #C7001F;
    }

    /* Responsive */
    @media (max-width: 640px) {
      .main-content {
        padding: 2rem 1.25rem 6rem;
      }

      .logo-mark {
        font-size: 2rem;
