        gap: 0.625rem;
      }

      .cookie-banner {
        padding: 1rem 1.25rem;
      }

      .cookie-content {
        gap: 0.625rem;
      }
    }

    @media (min-width: 768px) {
      .nav-links {
        flex-direction: row;
        gap: 2rem;
      }

      .cookie-content {
        flex-direction: row;
